create function touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table partners (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, owner text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table tracks (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, artist text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table periods (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, start_on date not null, end_on date not null, due_on date not null, currency text not null check(currency ~ '^[A-Z]{3}$'), status text not null default 'open' check(status in ('open','locked')), revision integer not null default 0, source_review text, reviewed_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(end_on>=start_on));
create table contracts (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, partner_id uuid not null references partners, track_id uuid not null references tracks, rate numeric(7,4) not null check(rate>0 and rate<=100), start_on date not null, end_on date not null, currency text not null check(currency ~ '^[A-Z]{3}$'), opening_debt numeric(20,6) not null default 0 check(opening_debt>=0), source text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(end_on>=start_on));
create table imports (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, period_id uuid not null references periods, fingerprint text not null, raw_text text not null, source text not null, actor text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(period_id,fingerprint));
create table sales (id uuid primary key default gen_random_uuid(), period_id uuid not null references periods, import_id uuid references imports, row_no integer not null, track_id uuid references tracks, reported_isrc text not null, territory text not null, reseller text not null, units numeric(20,6) not null, net_amount numeric(20,6) not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(import_id,row_no));
create table costs (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, contract_id uuid not null references contracts, period_id uuid not null references periods, amount numeric(20,6) not null check(amount>0), source text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table actions (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, period_id uuid not null references periods, owner text not null, due_on date not null, result text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table statements (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, period_id uuid not null references periods, contract_id uuid not null references contracts, currency text not null, revision integer not null, earned_amount numeric(20,6) not null, opening_amount numeric(20,6) not null, cost_amount numeric(20,6) not null, recouped_amount numeric(20,6) not null, closing_amount numeric(20,6) not null, available_amount numeric(20,6) not null, prepared_by text not null, approved_by text, snapshot jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(period_id,contract_id));
create table activity (id uuid primary key default gen_random_uuid(), name text not null, actor text not null, detail jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table settings (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, retention_years integer not null default 7 check(retention_years>=7), backup_checked_on date, backup_evidence text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
insert into settings(code,name) values('OPERATOR','Royalty working record');
do $$ declare t text; begin foreach t in array array['partners','tracks','periods','contracts','imports','sales','costs','actions','statements','activity','settings'] loop execute format('create trigger touch before update on %I for each row execute function touch_updated_at()',t); execute format('alter table %I enable row level security',t); execute format('revoke all on %I from public',t); end loop; end $$;
create view v_unmatched as select p.code period,s.id,s.reported_isrc,s.territory,s.reseller,s.units,s.net_amount from sales s join periods p on p.id=s.period_id where s.track_id is null;
create view v_earned as select p.id period_id,p.code period,c.id contract_id,c.code contract,c.name,pa.name partner,t.name track,p.currency,c.rate,coalesce(sum(s.net_amount),0)::numeric(20,6) net_amount,round(coalesce(sum(s.net_amount),0)*c.rate/100,6)::numeric(20,6) earned_amount from periods p join contracts c on c.start_on<=p.start_on and c.end_on>=p.end_on and c.currency=p.currency join partners pa on pa.id=c.partner_id join tracks t on t.id=c.track_id left join sales s on s.period_id=p.id and s.track_id=c.track_id group by p.id,c.id,pa.name,t.name;
create view v_recoupment as select e.*, coalesce(prev.closing_amount,c.opening_debt)::numeric(20,6) opening_amount, coalesce(cost.amount,0)::numeric(20,6) cost_amount, least(greatest(e.earned_amount,0),coalesce(prev.closing_amount,c.opening_debt)+coalesce(cost.amount,0))::numeric(20,6) recouped_amount, greatest(coalesce(prev.closing_amount,c.opening_debt)+coalesce(cost.amount,0)-e.earned_amount,0)::numeric(20,6) closing_amount, greatest(e.earned_amount-coalesce(prev.closing_amount,c.opening_debt)-coalesce(cost.amount,0),0)::numeric(20,6) available_amount from v_earned e join contracts c on c.id=e.contract_id join periods current_period on current_period.id=e.period_id left join lateral(select s.closing_amount from statements s join periods pp on pp.id=s.period_id where s.contract_id=c.id and pp.end_on<current_period.start_on and pp.status='locked' order by pp.end_on desc limit 1) prev on true left join lateral(select sum(amount) amount from costs where period_id=e.period_id and contract_id=e.contract_id) cost on true;
create view v_attention as select p.code period,p.currency,p.due_on,p.status,(select count(*) from sales s where s.period_id=p.id and s.track_id is null) unmatched,(select count(*) from actions a where a.period_id=p.id and a.result is null) open_actions,(select count(*) from statements s where s.period_id=p.id and s.approved_by is null) unapproved,case when p.source_review is null then 'Source review owed' else 'Source reviewed' end source_review from periods p where p.status='open';
create view v_income as select p.code period,p.currency,s.reseller,s.territory,count(*) lines,sum(s.units) units,sum(s.net_amount)::numeric(20,6) net_amount from sales s join periods p on p.id=s.period_id group by p.code,p.currency,s.reseller,s.territory;
